<?php
function tickex_mobile_datetime($value)
{
    if ($value === null || trim((string)$value) === '') return null;
    $timestamp = strtotime((string)$value);
    return $timestamp === false ? null : date('c', $timestamp);
}
require_once __DIR__ . '/../inc/mobile_admin.php';
function admin_event_assert($condition, $message)
{
    if (!$condition) { fwrite(STDERR, "FAIL: " . $message . "\n"); exit(1); }
}
date_default_timezone_set('America/Argentina/Buenos_Aires');
$pdo = new PDO('sqlite::memory:');
$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
$pdo->exec("CREATE TABLE eventos (id INTEGER PRIMARY KEY, nombre TEXT, slug TEXT UNIQUE, descripcion TEXT, fecha_desde TEXT, fecha_hasta TEXT, lugar TEXT, creado_por_admin_id INTEGER, creado_en TEXT, actualizado_en TEXT, publicado_site INTEGER DEFAULT 0, borrado_en TEXT)");
$owner = array('id' => 7, 'tipo_global' => 'admin_evento');
$other = array('id' => 8, 'tipo_global' => 'admin_evento');
$created = tickex_mobile_admin_create_event($pdo, $owner, array('name' => 'Evento de prueba', 'slug' => 'evento-prueba', 'description' => 'Prueba', 'startsAt' => '2026-10-05T20:00:00-03:00', 'endsAt' => '2026-10-06T03:00:00-03:00', 'venue' => 'Sala'));
admin_event_assert(isset($created['id']) && $created['published'] === false, 'creates private draft for owner');
$eventId = (int)$created['id'];
admin_event_assert($created['endsAt'] !== null, 'returns end date');
admin_event_assert(count(tickex_mobile_admin_events($pdo, $owner)) === 1, 'owner sees event');
admin_event_assert(count(tickex_mobile_admin_events($pdo, $other)) === 0, 'other producer cannot list event');
admin_event_assert(tickex_mobile_admin_event_detail($pdo, $other, $eventId) === null, 'other producer cannot read detail');
admin_event_assert(tickex_mobile_admin_create_event($pdo, $owner, array('name' => 'Duplicado', 'slug' => 'evento-prueba'))['error'] === 'slug_in_use', 'duplicate slug rejected');
$updated = tickex_mobile_admin_edit_event($pdo, $owner, $eventId, array('name' => 'Nombre nuevo', 'description' => 'Actualizado', 'startsAt' => '2026-10-05T20:00:00-03:00', 'endsAt' => '2026-10-06T03:00:00-03:00', 'venue' => 'Sala 2'));
admin_event_assert($updated['name'] === 'Nombre nuevo' && $updated['venue'] === 'Sala 2', 'owner edits event');
admin_event_assert(tickex_mobile_admin_edit_event($pdo, $other, $eventId, array('name' => 'Intrusión'))['error'] === 'not_found', 'other producer cannot edit');
admin_event_assert(tickex_mobile_admin_create_event($pdo, $owner, array('name' => 'Mala fecha', 'slug' => 'mala-fecha', 'startsAt' => 'yesterday'))['error'] === 'invalid_event', 'relative dates rejected');
$pdo->exec("CREATE TABLE staff_roles (id INTEGER PRIMARY KEY, owner_admin_id INTEGER, code TEXT, name TEXT, permissions_json TEXT, activo INTEGER, is_system INTEGER, created_at TEXT, updated_at TEXT)");
$pdo->exec("CREATE TABLE staff_admins (id INTEGER PRIMARY KEY, owner_admin_id INTEGER, cliente_id INTEGER, rol_staff TEXT, activo INTEGER)");
$pdo->exec("CREATE TABLE staff_eventos (id INTEGER PRIMARY KEY, staff_id INTEGER, evento_id INTEGER, costo_servicio REAL DEFAULT 0, rol_staff TEXT, UNIQUE(staff_id, evento_id))");
$pdo->exec("CREATE TABLE registro_pendientes (id INTEGER PRIMARY KEY, nombre TEXT, apellido TEXT, apodo TEXT, email TEXT)");
$pdo->exec("CREATE TABLE staff_admin_invitaciones (id INTEGER PRIMARY KEY, owner_admin_id INTEGER, email TEXT, estado TEXT, created_at TEXT)");
$pdo->exec("INSERT INTO staff_roles (owner_admin_id, code, name, permissions_json, activo, is_system) VALUES (7, 'puerta', 'Puerta', '[\"checkin_scan\"]', 1, 1)");
$pdo->exec("INSERT INTO staff_roles (owner_admin_id, code, name, permissions_json, activo, is_system) VALUES (7, 'ventas', 'Ventas', '[\"sales_view\"]', 1, 0)");
$pdo->exec("INSERT INTO staff_admins VALUES (1, 7, 101, 'puerta', 1), (2, 8, 102, 'puerta', 1)");
$pdo->exec("INSERT INTO registro_pendientes VALUES (101, 'QA', 'Staff', '', 'staff@example.invalid'), (102, 'Otro', 'Staff', '', 'otro@example.invalid')");
$staff = tickex_mobile_admin_staff($pdo, $owner, $eventId);
admin_event_assert(count($staff['members']) === 1 && !$staff['members'][0]['assigned'], 'lists only producer staff');
admin_event_assert(tickex_mobile_admin_assign_staff($pdo, $owner, $eventId, 102, 'puerta', true)['error'] === 'staff_not_found', 'cannot assign another producer staff');
$staff = tickex_mobile_admin_assign_staff($pdo, $owner, $eventId, 101, 'puerta', true);
admin_event_assert($staff['members'][0]['assigned'] && $staff['members'][0]['roleCode'] === 'puerta', 'assigns authorized staff with event role');
$pdo->exec("UPDATE staff_eventos SET costo_servicio = 55 WHERE staff_id = 101 AND evento_id = $eventId");
tickex_mobile_admin_assign_staff($pdo, $owner, $eventId, 101, 'puerta', true);
admin_event_assert((float)$pdo->query("SELECT costo_servicio FROM staff_eventos WHERE staff_id = 101 AND evento_id = $eventId")->fetchColumn() === 55.0, 'role update preserves existing event staff cost');
$secondEvent = tickex_mobile_admin_create_event($pdo, $owner, array('name' => 'Segundo evento', 'slug' => 'segundo-evento', 'startsAt' => '2026-11-10T20:00:00-03:00', 'venue' => 'Sala'));
$secondStaff = tickex_mobile_admin_assign_staff($pdo, $owner, (int)$secondEvent['id'], 101, 'ventas', true);
admin_event_assert($secondStaff['members'][0]['roleCode'] === 'ventas', 'second event has its own role');
admin_event_assert(tickex_mobile_admin_staff($pdo, $owner, $eventId)['members'][0]['roleCode'] === 'puerta', 'assigning second event does not alter first event role');
$staff = tickex_mobile_admin_assign_staff($pdo, $owner, $eventId, 101, '', false);
admin_event_assert(!$staff['members'][0]['assigned'], 'removes staff assignment');
admin_event_assert(tickex_mobile_admin_staff($pdo, $owner, (int)$secondEvent['id'])['members'][0]['assigned'], 'removing first assignment preserves second');
$roles = tickex_mobile_admin_roles($pdo, $owner, $eventId);
admin_event_assert(isset($roles['catalog']['checkin_scan']) && count($roles['roles']) >= 2, 'producer reads role catalog');
admin_event_assert(tickex_mobile_admin_roles($pdo, $other, $eventId)['error'] === 'forbidden', 'other producer cannot read roles');
$createdRoles = tickex_mobile_admin_create_role($pdo, $owner, $eventId, array('code' => 'qa_evento', 'name' => 'QA', 'permissions' => array('checkin_scan', 'checkin_scan')));
admin_event_assert(count($createdRoles['roles']) === count($roles['roles']) + 1, 'creates custom role');
admin_event_assert(tickex_mobile_admin_create_role($pdo, $owner, $eventId, array('code' => 'qa_evento', 'name' => 'QA', 'permissions' => array()))['error'] === 'role_exists', 'rejects duplicate role');
admin_event_assert(tickex_mobile_admin_create_role($pdo, $owner, $eventId, array('code' => 'unsafe', 'name' => 'Unsafe', 'permissions' => array('admin_all')))['error'] === 'invalid_role', 'rejects unknown permission');
$customRoleId = (int)$pdo->query("SELECT id FROM staff_roles WHERE owner_admin_id = 7 AND code = 'qa_evento'")->fetchColumn();
admin_event_assert(tickex_mobile_admin_update_role($pdo, $other, $eventId, $customRoleId, array('name' => 'Intruso', 'permissions' => array()))['error'] === 'forbidden', 'other producer cannot edit role');
tickex_mobile_admin_update_role($pdo, $owner, $eventId, $customRoleId, array('name' => 'QA puerta', 'permissions' => array('tickets_validate')));
admin_event_assert($pdo->query("SELECT name FROM staff_roles WHERE id = $customRoleId")->fetchColumn() === 'QA puerta', 'updates own role');
tickex_mobile_admin_assign_staff($pdo, $owner, (int)$secondEvent['id'], 101, 'qa_evento', true);
admin_event_assert(tickex_mobile_admin_delete_role($pdo, $owner, $eventId, $customRoleId)['error'] === 'role_in_use', 'cannot delete role assigned in another event');
tickex_mobile_admin_assign_staff($pdo, $owner, (int)$secondEvent['id'], 101, '', false);
admin_event_assert(!isset(tickex_mobile_admin_delete_role($pdo, $owner, $eventId, $customRoleId)['error']), 'deletes unused custom role');
admin_event_assert(tickex_mobile_admin_delete_role($pdo, $owner, $eventId, 1)['error'] === 'system_role', 'cannot delete system role');
$pdo->exec('CREATE TABLE tipos_entrada (id INTEGER PRIMARY KEY, evento_id INTEGER, nombre TEXT, tipo TEXT NOT NULL, tipo_venta TEXT, precio REAL, cantidad_total INTEGER, cantidad_disponible INTEGER, visible_publico INTEGER, qr_quantity INTEGER, activo INTEGER)');
$pdo->exec("INSERT INTO tipos_entrada (id, evento_id, nombre, tipo, tipo_venta, precio, cantidad_total, cantidad_disponible, visible_publico, qr_quantity, activo) VALUES (10, $eventId, 'General', 'PAGA', 'PAGA', 100, 20, 20, 1, 1, 1)");
$stock = tickex_mobile_admin_update_ticket_type($pdo, $owner, $eventId, 10, array('expectedAvailable' => 20, 'available' => 5, 'visible' => false));
admin_event_assert($stock[0]['available'] === 5 && !$stock[0]['visible'] && $stock[0]['total'] === 5, 'owner adjusts stock and visibility');
admin_event_assert(tickex_mobile_admin_update_ticket_type($pdo, $owner, $eventId, 10, array('expectedAvailable' => 20, 'available' => 0, 'visible' => false))['error'] === 'stock_changed', 'stale stock edit rejected');
admin_event_assert(tickex_mobile_admin_update_ticket_type($pdo, $other, $eventId, 10, array('expectedAvailable' => 5, 'available' => 0, 'visible' => false))['error'] === 'forbidden', 'other producer cannot edit stock');
admin_event_assert(tickex_mobile_admin_set_publication($pdo, $owner, $eventId, true)['error'] === 'no_public_tickets', 'event without public stock cannot be published');
tickex_mobile_admin_update_ticket_type($pdo, $owner, $eventId, 10, array('expectedAvailable' => 5, 'available' => 5, 'visible' => true));
admin_event_assert(tickex_mobile_admin_set_publication($pdo, $owner, $eventId, true)['published'] === true, 'owner publishes ready event');
admin_event_assert(tickex_mobile_admin_set_publication($pdo, $other, $eventId, false)['error'] === 'forbidden', 'other producer cannot unpublish event');
admin_event_assert(tickex_mobile_admin_set_publication($pdo, $owner, $eventId, false)['published'] === false, 'owner hides event without deleting it');
admin_event_assert(tickex_mobile_admin_create_ticket_type($pdo, $other, $eventId, array('name' => 'Intruso', 'channel' => 'public', 'price' => 100, 'quantity' => 10, 'qrQuantity' => 1))['error'] === 'forbidden', 'other producer cannot create ticket type');
$newTypes = tickex_mobile_admin_create_ticket_type($pdo, $owner, $eventId, array('name' => 'Puerta', 'channel' => 'door', 'price' => 200, 'quantity' => 10, 'qrQuantity' => 1));
admin_event_assert(count($newTypes) === 2 && $newTypes[1]['visible'] === false, 'door type is created hidden from public checkout');
$newEvent = tickex_mobile_admin_create_event($pdo, $owner, array('name' => 'Nuevo', 'slug' => 'nuevo-evento', 'startsAt' => '2026-11-05T21:00:00-03:00', 'venue' => 'Sala'));
$newId = (int)$newEvent['id'];
admin_event_assert(tickex_mobile_admin_set_publication($pdo, $owner, $newId, true)['error'] === 'no_public_tickets', 'new draft requires public inventory');
tickex_mobile_admin_create_ticket_type($pdo, $owner, $newId, array('name' => 'General', 'channel' => 'public', 'price' => 150, 'quantity' => 12, 'qrQuantity' => 1));
admin_event_assert(tickex_mobile_admin_set_publication($pdo, $owner, $newId, true)['published'] === true, 'new event with public inventory can be published');
echo "mobile admin events PASS\n";
